"""SCMOVS update: emails may be @gmail.com or @holycross.edu.ph (and nothing else).

  * Every email field (Users, Students, Profile, Forgot Password) accepts ONLY @gmail.com and @holycross.edu.ph.
  * Students: a personal @gmail.com address (for example khenrodc@gmail.com) OR their own school address
    <8-digit Student ID>@holycross.edu.ph (the number must match their Student ID).

HOW TO USE
  1. Put this file in your project folder (the folder that contains run.py).
  2. In PowerShell, inside that folder, run:   python apply_email_update.py
  3. Restart the app (python run.py) and press Ctrl+F5 in the browser.
  4. Optional: python database/check_email_domains.py   (lists existing accounts with other email domains)

Your current copy of every file it replaces is saved first in _update_backup/ (same sub-folders).
"""
import base64
import os
import shutil
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
FILES = {
    'app/validators.py': "",
    'app/auth/recovery.py': "",
    'static/js/form_rules.js': "",
    'templates/students/_form_modal.html': "",
    'templates/super_admin/users/_form_modal.html': "",
    'templates/profile/_edit_modal.html': "",
    'templates/auth/_forgot_modal.html': "",
    'database/check_email_domains.py': "",
    'tests/test_users.py': "",
    'tests/test_students_depts.py': "",
    'tests/test_profile_recovery.py': "",
    'tests/test_email_domains.py': "",
    'tests/run_all.sh': "",
}


def main():
    if not os.path.isfile(os.path.join(ROOT, "run.py")) or not os.path.isdir(os.path.join(ROOT, "app")):
        print("STOP: put this file in your project folder (the one that has run.py and the app folder), then run it again.")
        sys.exit(1)
    for rel, encoded in FILES.items():
        target = os.path.join(ROOT, *rel.split("/"))
        if os.path.isfile(target):
            saved = os.path.join(ROOT, "_update_backup", *rel.split("/"))
            os.makedirs(os.path.dirname(saved), exist_ok=True)
            if not os.path.exists(saved):
                shutil.copy2(target, saved)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "wb") as handle:
            handle.write(base64.b64decode(encoded))
        print("  updated", rel)
    print("\nDone. Restart the app (python run.py) and press Ctrl+F5 in the browser.")


if __name__ == "__main__":
    main()
